export type Maybe<T> = T | null;
export type InputMaybe<T> = Maybe<T>;
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string; }
  String: { input: string; output: string; }
  Boolean: { input: boolean; output: boolean; }
  Int: { input: number; output: number; }
  Float: { input: number; output: number; }
  /** An ISO 8601-encoded datetime */
  ISO8601DateTime: { input: unknown; output: unknown; }
};

/** Autogenerated return type of CollectionSynced. */
export type CollectionSyncedPayload = {
  __typename?: 'CollectionSyncedPayload';
  error?: Maybe<Scalars['String']['output']>;
  gameCount?: Maybe<Scalars['Int']['output']>;
  lastSyncedAt?: Maybe<Scalars['ISO8601DateTime']['output']>;
  status: SyncStatus;
  username: Scalars['String']['output'];
};

export type HotItem = {
  __typename?: 'HotItem';
  /** BGG thing ID for this hot item. */
  id: Scalars['ID']['output'];
  /** Primary name of the game. */
  name: Scalars['String']['output'];
  /** Rank on the BGG hotness list. */
  rank: Scalars['Int']['output'];
  /** Thumbnail image URL. */
  thumbnail?: Maybe<Scalars['String']['output']>;
  /** Year the game was published. */
  yearPublished?: Maybe<Scalars['Int']['output']>;
};

/** Autogenerated return type of ImportCollection. */
export type ImportCollectionPayload = {
  __typename?: 'ImportCollectionPayload';
  /** The local user record for the requested BGG username */
  user: User;
};

export type MergedCollection = {
  __typename?: 'MergedCollection';
  items: Array<MergedThing>;
  syncStatuses: Array<UserSyncStatus>;
};

export type MergedThing = {
  __typename?: 'MergedThing';
  average?: Maybe<Scalars['Float']['output']>;
  averageWeight?: Maybe<Scalars['Float']['output']>;
  bayesAverage?: Maybe<Scalars['Float']['output']>;
  description?: Maybe<Scalars['String']['output']>;
  id: Scalars['ID']['output'];
  image?: Maybe<Scalars['String']['output']>;
  isExpansion: Scalars['Boolean']['output'];
  maxPlayers?: Maybe<Scalars['Int']['output']>;
  maxPlaytime?: Maybe<Scalars['Int']['output']>;
  minAge?: Maybe<Scalars['Int']['output']>;
  minPlayers?: Maybe<Scalars['Int']['output']>;
  minPlaytime?: Maybe<Scalars['Int']['output']>;
  name: Scalars['String']['output'];
  owners: Array<Owner>;
  thumbnail?: Maybe<Scalars['String']['output']>;
  usersRated?: Maybe<Scalars['Int']['output']>;
  yearPublished?: Maybe<Scalars['Int']['output']>;
};

export type Mutation = {
  __typename?: 'Mutation';
  /** Enqueue a BGG collection import for a username and return the user with initial sync status. */
  importCollection?: Maybe<ImportCollectionPayload>;
  /** Validate a BGG username format and existence. */
  validateBggUsername?: Maybe<ValidateBggUsernamePayload>;
};


export type MutationImportCollectionArgs = {
  username: Scalars['String']['input'];
};


export type MutationValidateBggUsernameArgs = {
  username: Scalars['String']['input'];
};

export type Owner = {
  __typename?: 'Owner';
  avatar?: Maybe<Scalars['String']['output']>;
  bggUsername: Scalars['String']['output'];
};

export type Query = {
  __typename?: 'Query';
  /** Health check — proves the GraphQL endpoint is alive. */
  health: Scalars['String']['output'];
  /** The current BoardGameGeek hotness list. */
  hotItems: Array<HotItem>;
  /** Merge and deduplicate the BGG collections for the given usernames. */
  mergedCollection: MergedCollection;
  /** Search BoardGameGeek for games matching the query. */
  search: Array<SearchResult>;
  /** Look up a local user by their BGG username. */
  user?: Maybe<User>;
};


export type QueryMergedCollectionArgs = {
  usernames: Array<Scalars['String']['input']>;
};


export type QuerySearchArgs = {
  query: Scalars['String']['input'];
};


export type QueryUserArgs = {
  username: Scalars['String']['input'];
};

export type SearchResult = {
  __typename?: 'SearchResult';
  /** BGG thing ID for the search result. */
  id: Scalars['ID']['output'];
  /** Name of the game. */
  name: Scalars['String']['output'];
  /** Year the game was published. */
  yearPublished?: Maybe<Scalars['Int']['output']>;
};

export type Subscription = {
  __typename?: 'Subscription';
  /** Real-time sync status updates for a BGG username's collection import. */
  collectionSynced: CollectionSyncedPayload;
};


export type SubscriptionCollectionSyncedArgs = {
  username: Scalars['String']['input'];
};

export enum SyncStatus {
  /** Import failed */
  Error = 'ERROR',
  /** Import is queued and waiting to start */
  Queued = 'QUEUED',
  /** Import completed successfully */
  Ready = 'READY',
  /** Import is in progress */
  Syncing = 'SYNCING'
}

export type User = {
  __typename?: 'User';
  avatar?: Maybe<Scalars['String']['output']>;
  id: Scalars['ID']['output'];
  syncStatus: UserSyncStatus;
  username: Scalars['String']['output'];
};

export type UserSyncStatus = {
  __typename?: 'UserSyncStatus';
  error?: Maybe<Scalars['String']['output']>;
  gameCount?: Maybe<Scalars['Int']['output']>;
  lastSyncedAt?: Maybe<Scalars['ISO8601DateTime']['output']>;
  status: SyncStatus;
  username: Scalars['String']['output'];
};

/** Autogenerated return type of ValidateBggUsername. */
export type ValidateBggUsernamePayload = {
  __typename?: 'ValidateBggUsernamePayload';
  validationResult: ValidationResult;
};

export type ValidationResult = {
  __typename?: 'ValidationResult';
  /** Avatar URL for the BGG user, if present. */
  avatar?: Maybe<Scalars['String']['output']>;
  /** Whether the username exists on BoardGameGeek. */
  exists: Scalars['Boolean']['output'];
  /** The normalized username that was validated. */
  username: Scalars['String']['output'];
  /** Whether the input passed the format contract. */
  valid: Scalars['Boolean']['output'];
};
